<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f17;
      --panel: rgba(18, 24, 38, 0.92);
      --panel-strong: #121827;
      --panel-soft: #1a2334;
      --line: rgba(148, 163, 184, 0.22);
      --text: #e5eefc;
      --muted: #97a3b6;
      --accent: #7c9cff;
      --danger: #ff6b7a;
      --danger-strong: #ff4d61;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 35%),
        linear-gradient(180deg, #0f1727 0%, var(--bg) 100%);
      color: var(--text);
    }

    .preview-shell {
      width: min(100%, 960px);
      display: grid;
      gap: 24px;
    }

    .eyebrow {
      margin: 0 0 10px;
      font-size: 0.8rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
    }

    .preview-card {
      display: grid;
      gap: 20px;
      padding: 24px;
      border: 1px solid var(--line);
      border-radius: 28px;
      background: var(--panel);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .image-frame {
      overflow: hidden;
      border-radius: var(--radius);
      border: 1px solid rgba(148, 163, 184, 0.18);
      background: #05070c;
      aspect-ratio: 16 / 10;
    }

    .image-frame img {
      width: 100%;
      height: 100%;
      display: block;
      object-fit: cover;
    }

    .preview-meta {
      display: flex;
      justify-content: space-between;
      gap: 24px;
      align-items: end;
      flex-wrap: wrap;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.8rem);
    }

    .description {
      margin: 8px 0 0;
      max-width: 60ch;
      color: var(--muted);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.18s ease, opacity 0.18s ease, background 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
    }

    .secondary {
      background: var(--panel-soft);
      color: var(--text);
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .danger {
      background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
      color: #fff;
      box-shadow: 0 12px 30px rgba(255, 77, 97, 0.28);
    }

    .modal[hidden] {
      display: none;
    }

    .modal {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(2, 6, 14, 0.72);
      backdrop-filter: blur(10px);
    }

    .modal-panel {
      width: min(100%, 460px);
      padding: 28px;
      border-radius: 26px;
      background: linear-gradient(180deg, rgba(25, 34, 52, 0.96) 0%, rgba(14, 19, 31, 0.98) 100%);
      border: 1px solid rgba(148, 163, 184, 0.16);
      box-shadow: var(--shadow);
    }

    .modal-panel h2 {
      margin: 0 0 12px;
      font-size: 1.5rem;
    }

    .modal-panel p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
      flex-wrap: wrap;
    }

    .status {
      min-height: 1.5em;
      margin-top: 12px;
      color: #8ce3b0;
      font-weight: 600;
    }

    @media (max-width: 640px) {
      body {
        padding: 18px;
      }

      .preview-card,
      .modal-panel {
        padding: 20px;
      }

      .modal-actions,
      .actions {
        flex-direction: column;
      }

      .modal-actions button,
      .actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="preview-shell">
    <section class="preview-card">
      <div class="image-frame">
        <img
          src="https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=1400&q=80"
          alt="Snowy mountain landscape under a star-filled sky"
        >
      </div>

      <div class="preview-meta">
        <div>
          <p class="eyebrow">Image preview</p>
          <h1>Midnight Ridge</h1>
          <p class="description">
            Review the selected image before making changes to your library. Deleting it will remove it from your saved collection.
          </p>
          <p class="status" id="status" aria-live="polite"></p>
        </div>

        <div class="actions">
          <button type="button" class="secondary">Download</button>
          <button type="button" class="danger trigger" id="open-dialog">Delete image</button>
        </div>
      </div>
    </section>
  </main>

  <div class="modal" id="delete-dialog" hidden>
    <div
      class="modal-panel"
      role="dialog"
      aria-modal="true"
      aria-labelledby="dialog-title"
      aria-describedby="dialog-description"
    >
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will permanently remove <strong>Midnight Ridge</strong> from your library. Are you sure you want to continue?
      </p>

      <div class="modal-actions">
        <button type="button" class="secondary" id="cancel-delete">Cancel</button>
        <button type="button" class="danger" id="confirm-delete">Delete</button>
      </div>
    </div>
  </div>

  <script>
    const openButton = document.getElementById("open-dialog");
    const modal = document.getElementById("delete-dialog");
    const cancelButton = document.getElementById("cancel-delete");
    const confirmButton = document.getElementById("confirm-delete");
    const status = document.getElementById("status");

    const closeDialog = () => {
      modal.hidden = true;
      openButton.focus();
    };

    openButton.addEventListener("click", () => {
      modal.hidden = false;
      cancelButton.focus();
    });

    cancelButton.addEventListener("click", closeDialog);

    confirmButton.addEventListener("click", () => {
      status.textContent = "Image deleted from your library.";
      closeDialog();
    });

    modal.addEventListener("click", (event) => {
      if (event.target === modal) {
        closeDialog();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && !modal.hidden) {
        closeDialog();
      }
    });
  </script>
</body>
</html>
