       width: min(100%, 960px);
       display: grid;
       gap: 24px;
     }

     .eyebrow {
       margin: 0 0 10px;
       font-size: 0.8rem;
       letter-spacing: 0.12em;
       text-transform: uppercase;
       color: var(--accent);
     }

     .preview-card {
       display: grid;
       gap: 20px;
       padding: 24px;
       border: 1px solid var(--line);
       border-radius: 28px;
       background: var(--panel);
       backdrop-filter: blur(18px);
       box-shadow: var(--shadow);
     }

     .image-frame {
       overflow: hidden;
       border-radius: var(--radius);
       border: 1px solid rgba(148, 163, 184, 0.18);
       background: #05070c;
       aspect-ratio: 16 / 10;
     }

     .image-frame img {
       width: 100%;
       height: 100%;
       display: block;
       object-fit: cover;
     }

     .preview-meta {
       display: flex;
       justify-content: space-between;
       gap: 24px;
       align-items: end;
       flex-wrap: wrap;
     }

     h1 {
       margin: 0;
       font-size: clamp(1.8rem, 4vw, 2.8rem);
     }

     .description {
       margin: 8px 0 0;
       max-width: 60ch;
       color: var(--muted);
       line-height: 1.6;
     }

     .actions {
       display: flex;
       gap: 12px;
       flex-wrap: wrap;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 14px 20px;
       font: inherit;
       font-weight: 600;
       cursor: pointer;
       transition: transform 0.18s ease, opacity 0.18s ease, background 0.18s ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 2px solid var(--accent);
       outline-offset: 3px;
     }

     .secondary {
       background: var(--panel-soft);
       color: var(--text);
       border: 1px solid rgba(148, 163, 184, 0.18);
     }

     .danger {
       background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
       color: #fff;
       box-shadow: 0 12px 30px rgba(255, 77, 97, 0.28);
     }

     .modal[hidden] {
       display: none;
     }

     .modal {
       position: fixed;
       inset: 0;
       display: grid;
       place-items: center;
       padding: 24px;
       background: rgba(2, 6, 14, 0.72);
       backdrop-filter: blur(10px);
     }

     .modal-panel {
       width: min(100%, 460px);
       padding: 28px;
       border-radius: 26px;
       background: linear-gradient(180deg, rgba(25, 34, 52, 0.96) 0%, rgba(14, 19, 31, 0.98) 100%);
       border: 1px solid rgba(148, 163, 184, 0.16);
       box-shadow: var(--shadow);
     }

     .modal-panel h2 {
       margin: 0 0 12px;
       font-size: 1.5rem;
     }

     .modal-panel p {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .modal-actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       margin-top: 24px;
       flex-wrap: wrap;
     }

     .status {
       min-height: 1.5em;
       margin-top: 12px;
       color: #8ce3b0;
       font-weight: 600;
     }

     @media (max-width: 640px) {
       body {
         padding: 18px;
       }

       .preview-card,
       .modal-panel {
         padding: 20px;
       }

       .modal-actions,
       .actions {
         flex-direction: column;
       }

       .modal-actions button,
       .actions button {
         width: 100%;
       }
     }
   </style>
 </head>
